begin;
select plan(8);
create temp table avatar_fixture(actor uuid, other uuid, path text);
insert into avatar_fixture values(gen_random_uuid(),gen_random_uuid(),null);
insert into auth.users(id,email) select actor,actor::text || '@example.invalid' from avatar_fixture union all select other,other::text || '@example.invalid' from avatar_fixture;
insert into public.user_profiles(id,full_name) select actor,'Avatar Tester' from avatar_fixture union all select other,'Other Person' from avatar_fixture on conflict (id) do nothing;
update avatar_fixture set path=actor::text || '/' || gen_random_uuid()::text || '.png';
insert into storage.objects(bucket_id,name) select 'user-avatars',path from avatar_fixture;
select ok(not has_function_privilege('anon','public.update_user_avatar(text,text)','EXECUTE'),'anonymous execution denied');
select set_config('request.jwt.claim.sub',(select actor::text from avatar_fixture),true);
select lives_ok($$select public.update_user_avatar(path,null) from avatar_fixture$$,'user can set an uploaded photo');
select is((select avatar_path from public.user_profiles where id=(select actor from avatar_fixture)),(select path from avatar_fixture),'photo path persisted');
select throws_ok($$select public.update_user_avatar(null,null)$$,'40001','Avatar changed; refresh and try again','stale editor cannot remove a newer photo');
select throws_ok($$select public.update_user_avatar(other::text || '/' || gen_random_uuid()::text || '.png',path) from avatar_fixture$$,'22023','Invalid avatar','another user''s folder is denied');
select throws_ok($$select public.update_user_avatar(actor::text || '/' || gen_random_uuid()::text || '.png',path) from avatar_fixture$$,'22023','Invalid avatar','missing object is denied');
select throws_ok($$update public.user_profiles set avatar_path=(select other::text from avatar_fixture) || '/' || gen_random_uuid()::text || '.png' where id=(select actor from avatar_fixture)$$,'23514',null,'profile cannot point outside its own folder');
select lives_ok($$select public.update_user_avatar(null,path) from avatar_fixture$$,'user can remove their photo');
select * from finish();
rollback;
